CREATE FUNCTION public.approved_hotel_score(_client uuid,_month date) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH p AS(SELECT cp.id,coalesce(cp.weight,pl.default_weight,1) weight,avg(e.achievement_pct) score FROM monthly_reports r JOIN client_pipelines cp ON cp.id=r.client_pipeline_id JOIN pipelines pl ON pl.id=cp.pipeline_id JOIN kpi_entries e ON e.report_id=r.id WHERE r.client_id=_client AND r.month=date_trunc('month',_month)::date AND r.status='approved' GROUP BY cp.id,cp.weight,pl.default_weight) SELECT round(sum(score*weight)/nullif(sum(weight) FILTER(WHERE score IS NOT NULL),0),1) FROM p $$;
REVOKE ALL ON FUNCTION public.approved_hotel_score(uuid,date) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.portfolio_report_health(_month date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.is_manager(auth.uid()) THEN RAISE EXCEPTION 'Management access required'; END IF; WITH scores AS(SELECT c.id,c.hotel_name,approved_hotel_score(c.id,_month) score,approved_hotel_score(c.id,(_month-interval '1 month')::date) previous_score FROM clients c WHERE NOT c.is_demo) SELECT jsonb_build_object('top',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM(SELECT * FROM scores WHERE score IS NOT NULL ORDER BY score DESC,hotel_name LIMIT 3)x),'[]'),'bottom',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM(SELECT * FROM scores WHERE score IS NOT NULL ORDER BY score,hotel_name LIMIT 3)x),'[]'),'at_risk',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM(SELECT * FROM scores WHERE scorecard_band(score)='red' AND scorecard_band(previous_score)='red')x),'[]')) INTO result; RETURN result; END $$;
DO $$ DECLARE s text; BEGIN SELECT pg_get_functiondef(oid) INTO s FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='hotel_scorecard'; s:=replace(s, 'WHEN (res->>''overall'')::numeric >= 90 THEN ''green'' WHEN (res->>''overall'')::numeric >= 70 THEN ''amber'' ELSE ''red'' END', 'ELSE public.scorecard_band((res->>''overall'')::numeric) END'); EXECUTE s; END $$;
CREATE FUNCTION public.q50_baseline_direct_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND OLD.status='approved' AND NOT public.is_manager(auth.uid()) THEN RAISE EXCEPTION 'Only management can change an approved baseline'; END IF; RETURN NEW; END $$;
CREATE TRIGGER q50_baseline_direct_guard BEFORE UPDATE ON public.pipeline_baselines FOR EACH ROW EXECUTE FUNCTION public.q50_baseline_direct_guard();
CREATE POLICY q52_am_review_update ON public.monthly_reports FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM clients c WHERE c.id=client_id AND c.account_manager_id=auth.uid()) AND status<>'approved') WITH CHECK(EXISTS(SELECT 1 FROM clients c WHERE c.id=client_id AND c.account_manager_id=auth.uid()) AND status<>'approved');
CREATE FUNCTION public.q52_am_fields_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_manager(auth.uid()) AND NOT public.manages_pipeline(OLD.client_pipeline_id) AND EXISTS(SELECT 1 FROM clients c WHERE c.id=OLD.client_id AND c.account_manager_id=auth.uid()) AND (to_jsonb(NEW)-'am_review_comment'-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'am_review_comment'-'updated_at') THEN RAISE EXCEPTION 'Account Manager review does not approve or alter the report'; END IF; RETURN NEW; END $$;
CREATE TRIGGER q52_am_fields_guard BEFORE UPDATE ON public.monthly_reports FOR EACH ROW EXECUTE FUNCTION public.q52_am_fields_guard();